def parse_port(text):
    try:
        port = int(text)
    except (TypeError, ValueError) as exc:
        raise ValueError('Порт должен быть целым числом') from exc
    if not 1 <= port <= 65535:
        raise ValueError('Порт должен быть от 1 до 65535')
    return port

